import { existsSync, writeFileSync } from "node:fs";

// Next 16 typegen reads this generated declaration before recreating it.
// Seed it only when deployment packaging has excluded the generated file.
if (!existsSync("next-env.d.ts")) {
  writeFileSync(
    "next-env.d.ts",
    `/// <reference types="next" />\n/// <reference types="next/image-types/global" />\n\n// NOTE: This file is generated by Next.js.\n`,
  );
}
